from datetime import datetime, timedelta

def penalty(reported, arrived, monthly_fee):
    delay = (arrived - reported).days + (arrived - reported).seconds / 86400
    if delay <= 2:
        return 0
    else:
        return monthly_fee * 0.02 * (delay - 2)

# Example calls
print(penalty(datetime(2022, 1, 1, 12, 0, 0), datetime(2022, 1, 3, 12, 0, 0), 100))  # Expected result: 20.0
print(penalty(datetime(2022, 1, 1, 12, 0, 0), datetime(2022, 1, 2, 12, 0, 0), 100))  # Expected result: 0
